"""A tiny task-list CLI."""
import argparse
import json
from pathlib import Path


def render(items):
    return "\n".join(item["title"] for item in items)


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument(
        "--status", choices=("all", "open", "done"), default="all",
        help="show all, open, or done tasks (default: all)",
    )
    args = parser.parse_args()
    items = json.loads(args.source.read_text())
    if args.status != "all":
        items = [
            item for item in items
            if item.get("done", False) == (args.status == "done")
        ]
    print(render(items))


if __name__ == "__main__":
    main()

