import os
from pathlib import Path
import subprocess
import sys
import unittest
from tasks import render


class RenderTests(unittest.TestCase):
    def test_preserves_titles_and_order(self):
        self.assertEqual(render([{"title": "Second"}, {"title": "First"}]), "Second\nFirst")

    def test_empty(self):
        self.assertEqual(render([]), "")


class CliTests(unittest.TestCase):
    def run_cli(self, *options):
        workspace = Path(__file__).resolve().parent
        return subprocess.run(
            [sys.executable, str(workspace / "tasks.py"),
             str(workspace / "sample.json"), *options],
            capture_output=True,
            text=True,
            env={**os.environ, "PYTHONDONTWRITEBYTECODE": "1"},
            check=False,
        )

    def assert_output(self, expected, *options):
        result = self.run_cli(*options)
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(result.stdout, expected)
        self.assertEqual(result.stderr, "")

    def test_default_shows_all_in_original_order(self):
        self.assert_output("Write report\nReview patch\nCheck references\n")

    def test_explicit_all_preserves_formatting(self):
        self.assert_output(
            "Write report\nReview patch\nCheck references\n", "--status", "all"
        )

    def test_open_preserves_relative_order(self):
        self.assert_output("Write report\nCheck references\n", "--status", "open")

    def test_done(self):
        self.assert_output("Review patch\n", "--status", "done")

    def test_invalid_status_reports_choices(self):
        result = self.run_cli("--status", "pending")
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stdout, "")
        for expected in ("--status", "invalid choice", "pending", "all", "open", "done"):
            self.assertIn(expected, result.stderr)

    def test_status_requires_a_value(self):
        result = self.run_cli("--status")
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stdout, "")
        self.assertIn("--status: expected one argument", result.stderr)

